import {readFile,writeFile,mkdir,chmod} from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
export function configPath() {return process.env.CREW_CONFIG??path.join(os.homedir(),'.config','crew','config.json');}
export async function readConfig(file=configPath()) {
  try{return JSON.parse(await readFile(file,'utf8'));}catch(error){if(error.code==='ENOENT')return {};throw new Error('Cannot read Crew config: '+error.message);}
}
export async function saveConfig(config,file=configPath()) {
  await mkdir(path.dirname(file),{recursive:true,mode:0o700});
  await writeFile(file,JSON.stringify(config,null,2)+'\n',{mode:0o600});
  await chmod(file,0o600);
}
export class CrewClient {
  constructor({url='http://localhost:4100',token,cookie}={}) {this.url=url.replace(/\/$/,'');this.token=token;this.cookie=cookie;}
  async request(method,route,body,options={}) {
    const headers={'X-Crew-Request':'1',...options.headers};
    if(this.token)headers.Authorization='Bearer '+this.token;
    else if(this.cookie)headers.Cookie=this.cookie;
    const raw=body instanceof Uint8Array;
    if(body!==undefined&&!raw)headers['Content-Type']='application/json';
    const response=await fetch(this.url+'/api/v1'+route,{method,headers,body:body===undefined?undefined:raw?body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});
    const cookie=response.headers.get('set-cookie');
    if(cookie)this.cookie=cookie.split(';')[0];
    if(options.binary){if(!response.ok)throw new Error('Download failed ('+response.status+')');return Buffer.from(await response.arrayBuffer());}
    const type=response.headers.get('content-type')??'';
    const data=type.includes('json')?await response.json():await response.text();
    if(!response.ok){const error=new Error(data.error?.message??'Request failed');error.code=data.error?.code;error.details=data.error?.details;error.status=response.status;throw error;}
    return data;
  }
  get(route,options){return this.request('GET',route,undefined,options);}
  post(route,body,options){return this.request('POST',route,body,options);}
  patch(route,body,options){return this.request('PATCH',route,body,options);}
  delete(route,body,options){return this.request('DELETE',route,body,options);}
}
export function query(values={}) {const search=new URLSearchParams(Object.entries(values).filter(([,v])=>v!==undefined&&v!==true));return search.size?'?'+search:'';}

export function table(items,columns) {
  if(!items.length)return 'No results';
  const keys=columns??Object.keys(items[0]).filter(k=>!['password','token','password_hash'].includes(k));
  const display=value=>value==null?'—':typeof value==='object'?JSON.stringify(value):String(value);
  const widths=keys.map(key=>Math.min(60,Math.max(key.length,...items.map(row=>display(row[key]).length))));
  const line=row=>keys.map((key,i)=>display(row[key]).slice(0,60).padEnd(widths[i])).join('  ').trimEnd();
  return [keys.map((key,i)=>key.padEnd(widths[i])).join('  ').trimEnd(),...items.map(line)].join('\n');
}
export function format(value,json=false) {
  if(json)return JSON.stringify(value,null,2);
  if(value?.items)return table(value.items);
  if(Array.isArray(value))return table(value);
  if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join('\n');
  return String(value??'');
}

