import express from 'express';
import { existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { loadConfig } from './config.js';
import { openDatabase, transaction } from './db/connection.js';
import { migrate } from './db/migrate.js';
import { createEventBus } from './events/bus.js';
import { authenticate, requireAuth } from './http/middleware/auth.js';
import { errorHandler, notFound, asyncRoute } from './http/errors.js';
import { paginate, pagination } from './http/pagination.js';
import { registerAuth } from './modules/auth/routes.js';
import { registerSse } from './http/sse.js';
export async function createApp(overrides={}) {
  const config=loadConfig(overrides);
  const db=openDatabase(config);
  await migrate(db);
  const app=express();
  const bus=createEventBus();
  const ctx={app,db,bus,config,requireAuth,asyncRoute,paginate,pagination,transaction:fn=>transaction(db,fn),id:()=>randomUUID(),now:()=>new Date().toISOString(),permissions:null,authenticateToken:null};
  app.disable('x-powered-by');
  app.use((req,res,next)=>{res.set('X-Content-Type-Options','nosniff');res.set('Referrer-Policy','same-origin');next();});
  app.use(express.json({limit:'2mb'}));
  app.use(authenticate(ctx));
  app.get('/api/v1/health',(req,res)=>res.json({ok:true}));
  registerAuth(ctx);
  for(const lane of ['people','work','insight']) {
    const url=new URL(`./modules/${lane}/routes.js`,import.meta.url);
    if(existsSync(url)){const module=await import(url);await module.registerRoutes(ctx);}
  }
  if(!ctx.sseRegistered)registerSse(ctx);
  const dist=fileURLToPath(new URL('../../web/dist/',import.meta.url));
  if(existsSync(dist)){app.use(express.static(dist));app.get('/',(req,res)=>res.sendFile('index.html',{root:dist}));}
  app.use(notFound);
  app.use(errorHandler);
  return {...ctx,close(){for(const cleanup of ctx.cleanups??[])cleanup();bus.clear();db.close();}};
}

import path from 'node:path';
export function loadConfig(overrides={}) {
  const config = {
    port: Number(process.env.PORT ?? 4100),
    dataDir: path.resolve(process.env.CREW_DATA_DIR ?? './data'),
    secret: process.env.CREW_SECRET ?? 'local-development-change-this-secret',
    maxUploadBytes: Number(process.env.CREW_MAX_UPLOAD_BYTES ?? 25*1024*1024),
    baseUrl: process.env.CREW_BASE_URL ?? 'http://localhost:4100',
    sessionDays: 14,
    ...overrides
  };
  if (!Number.isInteger(config.port) || config.port < 0 || config.port > 65535) throw new Error('Invalid PORT');
  if (!Number.isSafeInteger(config.maxUploadBytes) || config.maxUploadBytes < 1) throw new Error('Invalid CREW_MAX_UPLOAD_BYTES');
  return config;
}

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import path from 'node:path';
export function openDatabase(config) {
  mkdirSync(config.dataDir,{recursive:true,mode:0o700});
  const db = new DatabaseSync(path.join(config.dataDir,'crew.sqlite'));
  db.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA synchronous=OFF; PRAGMA busy_timeout=0;');
  return db;
}
export function transaction(db, fn) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    if (result && typeof result.then === 'function') throw new Error('Database transaction must be synchronous');
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}

import { readdir } from 'node:fs/promises';
import { transaction } from './connection.js';
export async function migrate(db) {
  db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');
  const names = (await readdir(new URL('./migrations/',import.meta.url))).filter(n=>/^\d+.*\.js$/.test(n)).sort();
  for (const name of names) {
    if (db.prepare('SELECT 1 FROM schema_migrations WHERE name=?').get(name)) continue;
    const module = await import(new URL('./migrations/'+name,import.meta.url));
    transaction(db,()=>{
      module.up(db);
      db.prepare('INSERT INTO schema_migrations VALUES (?,?)').run(name,new Date().toISOString());
    });
  }
}

export function up(db) {
  db.exec(`CREATE TABLE users (
    id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL,
    password_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
  );
  CREATE TABLE sessions (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL,
    last_used_at TEXT NOT NULL, user_agent TEXT NOT NULL DEFAULT ''
  );
  CREATE INDEX sessions_user ON sessions(user_id);`);
}

import { randomUUID } from 'node:crypto';
export function createEventBus() {
  const listeners = new Set();
  return {
    subscribe(listener) { listeners.add(listener); return ()=>listeners.delete(listener); },
    emit(input) {
      const event = {id:randomUUID(),actorId:null,orgId:null,projectId:null,before:null,after:null,time:new Date().toISOString(),...input};
      if (!event.entityType || !event.entityId || !event.action) throw new Error('Incomplete domain event');
      for (const listener of [...listeners]) listener(event);
      return event;
    },
    clear() { listeners.clear(); },
    get listenerCount() { return listeners.size; }
  };
}

import { AppError } from '@crew/shared';
export const asyncRoute = fn => (req,res,next)=>Promise.resolve().then(()=>fn(req,res,next)).catch(next);
export function notFound(req,res,next) {
  next(new AppError('NOT_FOUND','No route matches this request',404));
}
export function errorHandler(error,req,res,next) {
  if (res.headersSent) return next(error);
  let status = error.status ?? 500;
  let code = error.code ?? 'INTERNAL';
  if (error.type==='entity.too.large') {status=413;code='TOO_LARGE';}
  if (error.type==='entity.parse.failed') {status=400;code='BAD_REQUEST';}
  const message = status>=500 ? 'The request could not be completed' : error.message;
  if (status>=500) console.error(error);
  res.status(status).json({error:{code,message,details:error.details??null}});
}

import { createHash } from 'node:crypto';
import { AppError } from '@crew/shared';
export const hashToken = token => createHash('sha256').update(token).digest('hex');
export const publicUser = row => row ? {id:row.id,email:row.email,name:row.name,createdAt:row.created_at,updatedAt:row.updated_at} : null;
export function cookies(header='') {
  const result={};
  for (const item of header.split(';')) {
    const at=item.indexOf('=');
    if(at<0)continue;
    try {result[item.slice(0,at).trim()]=decodeURIComponent(item.slice(at+1));} catch {}
  }
  return result;
}
export function authenticate(ctx) {
  return (req,res,next)=>{
    try {
      req.user=null;
      req.auth=null;
      const bearer=/^Bearer (.+)$/i.exec(req.headers.authorization??'');
      if (bearer && ctx.authenticateToken) {
        const auth=ctx.authenticateToken(bearer[1]);
        if(auth){req.user=auth.user;req.auth=auth;}
      } else {
        const token=cookies(req.headers.cookie).crew_session;
        if(token){
          const session=ctx.db.prepare('SELECT * FROM sessions WHERE token_hash=? AND expires_at>?').get(hashToken(token),new Date().toISOString());
          if(session){
            req.user=publicUser(ctx.db.prepare('SELECT * FROM users WHERE id=?').get(session.user_id));
            req.auth={kind:'session',sessionId:session.id,user:req.user};
          }
        }
      }
      if(req.auth?.kind==='session'&&!['GET','HEAD','OPTIONS'].includes(req.method)&&req.headers['x-crew-request']!=='1') throw new AppError('FORBIDDEN','X-Crew-Request header is required',403);
      next();
    }catch(error){next(error);}
  };
}
export function requireAuth(req,res,next) {
  if(!req.user)return next(new AppError('UNAUTHENTICATED','Please sign in',401));
  next();
}

export const validate = schema => (req,res,next)=>{
  try {req.input=schema(req.body);next();} catch(error){next(error);}
};

import { AppError, integer } from '@crew/shared';
export function encodeCursor(value) { return Buffer.from(JSON.stringify(value)).toString('base64url'); }
export function decodeCursor(value) {
  if (!value) return null;
  try {
    const parsed = JSON.parse(Buffer.from(value,'base64url').toString());
    if (!parsed || typeof parsed !== 'object') throw new Error();
    return parsed;
  } catch { throw new AppError('VALIDATION','Invalid pagination cursor',422,{cursor:'Invalid cursor'}); }
}
export function pagination(query={}) {
  return {limit:integer(query.limit??50,'limit',{min:1,max:200}),cursor:decodeCursor(query.cursor)};
}
export function paginate(items,query={},key='id') {
  const {limit,cursor}=pagination(query);
  let start=0;
  if (cursor) {
    if (cursor.key!==key) throw new AppError('VALIDATION','Cursor belongs to another list',422);
    const index=items.findIndex(item=>String(item[key])===String(cursor.value));
    start=index<0?items.length:index+1;
  }
  const result=items.slice(start,start+limit);
  return {items:result,nextCursor:start+limit<items.length&&result.length?encodeCursor({key,value:result.at(-1)[key]}):null};
}

import { requireAuth } from './middleware/auth.js';
export function registerSse(ctx) {
  ctx.app.get('/api/v1/events',requireAuth,(req,res)=>res.status(503).json({error:{code:'NOT_READY',message:'Live updates will be available after insight integration',details:null}}));
}

import { createApp } from './app.js';
const ctx=await createApp();
const server=ctx.app.listen(ctx.config.port,'0.0.0.0',()=>{
  console.log(JSON.stringify({ready:true,port:server.address().port,pid:process.pid}));
});
let stopping=false;
function stop() {
  if(stopping)return;
  stopping=true;
  const deadline=setTimeout(()=>{server.closeAllConnections();ctx.close();process.exit(1);},3000);
  deadline.unref();
  server.close(()=>{clearTimeout(deadline);ctx.close();process.exit(0);});
  server.closeIdleConnections();
}
process.on('SIGTERM',stop);
process.on('SIGINT',stop);

import { scrypt as scryptCallback, randomBytes, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';
const scrypt=promisify(scryptCallback);
export async function hashPassword(password) {
  const salt=randomBytes(16).toString('hex');
  const derived=await scrypt(password,salt,64);
  return `scrypt:${salt}:${derived.toString('hex')}`;
}
export async function verifyPassword(password,stored) {
  const [kind,salt,digest]=String(stored).split(':');
  if(kind!=='scrypt'||!salt||!digest)return false;
  const candidate=await scrypt(password,salt,64);
  const expected=Buffer.from(digest,'hex');
  return candidate.length===expected.length&&timingSafeEqual(candidate,expected);
}

import { randomUUID, randomBytes } from 'node:crypto';
import { AppError, signupInput, loginInput } from '@crew/shared';
import { hashPassword, verifyPassword } from './passwords.js';
import { asyncRoute } from '../../http/errors.js';
import { hashToken, publicUser, requireAuth } from '../../http/middleware/auth.js';
export function registerAuth(ctx) {
  const {app,db,bus,config}=ctx;
  function session(req,res,user) {
    const token=randomBytes(32).toString('base64url');
    const time=new Date().toISOString();
    const expires=new Date(Date.now()+config.sessionDays*86400000).toISOString();
    const id=randomUUID();
    db.prepare('INSERT INTO sessions(id,user_id,token_hash,created_at,expires_at,last_used_at,user_agent) VALUES (?,?,?,?,?,?,?)').run(id,user.id,hashToken(token),time,expires,time,req.headers['user-agent']??'');
    res.cookie('crew_session',token,{httpOnly:true,sameSite:'strict',secure:false,path:'/',maxAge:config.sessionDays*86400000});
    return id;
  }
  app.post('/api/v1/auth/signup',asyncRoute(async(req,res)=>{
    const input=signupInput(req.body);
    if(db.prepare('SELECT id FROM users WHERE email=?').get(input.email))throw new AppError('CONFLICT','Email already registered',409);
    const id=randomUUID();
    const time=new Date().toISOString();
    const hash=await hashPassword(input.password);
    db.prepare('INSERT INTO users VALUES (?,?,?,?,?,?)').run(id,input.email,input.name,hash,time,time);
    const user=publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(id));
    session(req,res,user);
    bus.emit({actorId:id,entityType:'user',entityId:id,action:'created',after:user});
    res.status(201).json({user});
  }));
  app.post('/api/v1/auth/login',asyncRoute(async(req,res)=>{
    const input=loginInput(req.body);
    const row=db.prepare('SELECT * FROM users WHERE email=?').get(input.email);
    if(!row||!await verifyPassword(input.password,row.password_hash))throw new AppError('UNAUTHENTICATED','Email or password is incorrect',401);
    const user=publicUser(row);
    session(req,res,user);
    bus.emit({actorId:user.id,entityType:'user',entityId:user.id,action:'login',after:{email:user.email}});
    res.json({user});
  }));
  app.post('/api/v1/auth/logout',requireAuth,(req,res)=>{
    if(req.auth.kind==='session')db.prepare('DELETE FROM sessions WHERE id=?').run(req.auth.sessionId);
    res.clearCookie('crew_session',{path:'/'});
    bus.emit({actorId:req.user.id,entityType:'user',entityId:req.user.id,action:'logout'});
    res.json({ok:true});
  });
  app.get('/api/v1/me',requireAuth,(req,res)=>res.json({user:req.user,auth:{kind:req.auth.kind,scopes:req.auth.scopes??null}}));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
test('HTTP signup, session, CSRF protection and logout',async()=>{
  const s=await testServer();
  try{
    const request=s.agent();
    const signup=await request('POST','/auth/signup',{name:'Owner',email:'owner@example.test',password:'correct horse battery'});
    assert.equal(signup.status,201);
    assert.equal((await request('GET','/me')).data.user.email,'owner@example.test');
    const forbidden=await fetch(s.url+'/api/v1/auth/logout',{method:'POST',headers:{cookie:signup.cookie}});
    assert.equal(forbidden.status,403);
    assert.equal((await request('POST','/auth/logout',{})).status,200);
    assert.equal((await request('GET','/me')).status,401);
  }finally{await s.close();}
});

import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { once } from 'node:events';
import { createApp } from '../src/app.js';
export async function testServer(options={}) {
  const dataDir=await mkdtemp(path.join(tmpdir(),'crew-test-'));
  const ctx=await createApp({dataDir,secret:'test-secret',...options});
  const server=ctx.app.listen(0,'127.0.0.1');
  await once(server,'listening');
  const url=`http://127.0.0.1:${server.address().port}`;
  const agent=()=>{
    let cookie='';
    return async(method,route,body,extra={})=>{
      const headers={'X-Crew-Request':'1',...(cookie?{cookie}:{}),...(body!==undefined?{'content-type':'application/json'}:{}),...extra};
      const response=await fetch(url+'/api/v1'+route,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});
      if(response.headers.get('set-cookie'))cookie=response.headers.get('set-cookie').split(';')[0];
      const data=await response.json();
      return {status:response.status,data,response,cookie};
    };
  };
  return {ctx,server,url,agent,async close(){server.closeAllConnections();await new Promise(resolve=>server.close(resolve));ctx.close();await rm(dataDir,{recursive:true,force:true});}};
}

{
  "name": "@crew/shared",
  "version": "0.1.0",
  "type": "module",
  "private": true,
  "scripts": {
