export const ERROR_CODES = Object.freeze({
  VALIDATION: 'VALIDATION', UNAUTHENTICATED: 'UNAUTHENTICATED', FORBIDDEN: 'FORBIDDEN',
  NOT_FOUND: 'NOT_FOUND', CONFLICT: 'CONFLICT', BAD_REQUEST: 'BAD_REQUEST',
  RATE_LIMITED: 'RATE_LIMITED', TOO_LARGE: 'TOO_LARGE', INTERNAL: 'INTERNAL'
});
export class AppError extends Error {
  constructor(code, message, status = 400, details = null) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.status = status;
    this.details = details;
  }
}
export function fail(code, message, status = 400, details = null) {
  throw new AppError(code, message, status, details);
}
export function validation(details, message = 'Please correct the highlighted fields') {
  return new AppError('VALIDATION', message, 422, details);
}

export const EVENT_FIELDS = Object.freeze(['actorId','orgId','projectId','entityType','entityId','action','before','after','time']);
export const EVENT_NAMES = Object.freeze({USER_CREATED:'user.created',USER_LOGIN:'user.login',USER_LOGOUT:'user.logout'});
export function eventSummary(event) {
  return {id:event.id,actorId:event.actorId,orgId:event.orgId,projectId:event.projectId,entityType:event.entityType,entityId:event.entityId,action:event.action,time:event.time};
}

export * from './errors.js';
export * from './validate.js';
export * from './events.js';
export * from './schemas/user.js';

import { object, text, email } from '../validate.js';
export function signupInput(value) {
  const body = object(value);
  return {email:email(body.email),name:text(body.name,'name',{max:100}),password:text(body.password,'password',{min:10,max:1024,trim:false})};
}
export function loginInput(value) {
  const body = object(value);
  return {email:email(body.email),password:text(body.password,'password',{max:1024,trim:false})};
}

import { validation } from './errors.js';
export function object(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw validation({body:'Expected an object'});
  return value;
}
export function text(value, field, {min=1, max=255, optional=false, trim=true}={}) {
  if (value == null && optional) return null;
  if (typeof value !== 'string') throw validation({[field]:'Expected text'});
  const result = trim ? value.trim() : value;
  if (result.length < min || result.length > max) throw validation({[field]:`Must contain ${min} to ${max} characters`});
  return result;
}
export function email(value, field='email') {
  const result = text(value, field, {max:254}).toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(result)) throw validation({[field]:'Enter a valid email address'});
  return result;
}
export function choice(value, field, values, fallback) {
  const result = value ?? fallback;
  if (!values.includes(result)) throw validation({[field]:`Expected one of ${values.join(', ')}`});
  return result;
}
export function integer(value, field, {min=0,max=Number.MAX_SAFE_INTEGER,optional=false}={}) {
  if (value == null && optional) return null;
  const n = typeof value === 'string' && /^-?\d+$/.test(value) ? Number(value) : value;
  if (!Number.isSafeInteger(n) || n < min || n > max) throw validation({[field]:`Expected an integer from ${min} to ${max}`});
  return n;
}
export function date(value, field, {optional=false}={}) {
