export class ApiError extends Error {
  constructor(status,error){super(error?.message??`Request failed (${status})`);this.status=status;this.code=error?.code;this.details=error?.details;}
}
export function createApi(base='/api/v1',fetcher=globalThis.fetch) {
  async function request(method,path,body,options={}) {
    const headers={'X-Crew-Request':'1',...options.headers};
    const isRaw=body instanceof Blob||body instanceof ArrayBuffer||body instanceof Uint8Array;
    if(body!==undefined&&!isRaw)headers['Content-Type']='application/json';
    const response=await fetcher(base+path,{...options,method,headers,credentials:'same-origin',body:body===undefined?undefined:isRaw?body:JSON.stringify(body)});
    const type=response.headers.get('content-type')??'';
    const result=type.includes('application/json')?await response.json():await response.text();
    if(!response.ok)throw new ApiError(response.status,result.error);
    return result;
  }
  return {request,get:(path,options)=>request('GET',path,undefined,options),post:(path,body,options)=>request('POST',path,body,options),patch:(path,body,options)=>request('PATCH',path,body,options),put:(path,body,options)=>request('PUT',path,body,options),delete:(path,body,options)=>request('DELETE',path,body,options)};
}
export const api=createApi();
