    window.addEventListener('hashchange',change);
    api.get('/me').then(result=>store.set({user:result.user})).catch(()=>{}).finally(()=>setReady(true));
    return()=>window.removeEventListener('hashchange',change);
  },[]);
  if(!ready)return <main aria-busy="true">Opening Crew…</main>;
