  const effective=!state.user&&!publicPath?'/login':location.pathname;
  let matched=null;
  let params={};
  for(const route of routes){const result=matchRoute(route.path,effective);if(result){matched=route;params=result;break;}}
  const Component=matched?.component;
  async function logout(){await api.post('/auth/logout',{});store.set({user:null});navigate('/login');}
  return <div className="app-shell"><aside><a className="brand" href="#/">crew<span>team work</span></a>{state.user&&<nav aria-label="Main navigation">{navigation.map(item=><a href={'#'+item.path} aria-current={item.path===location.pathname?'page':undefined}>{item.label}</a>)}</nav>}<footer>{state.user&&<><span>{state.user.name}</span><button onClick={logout}>Sign out</button></>}</footer></aside><main><Notice>{state.notice}</Notice>{Component?<Component params={params} query={location.query} user={state.user} api={api} store={store} navigate={navigate}/>:<Page title="Page not found"><a href="#/">Return to overview</a></Page>}</main></div>;
}

