export function useLoad(load,deps=[]) {
  const [state,set]=useState({loading:true,data:null,error:null});
  const [version,refresh]=useState(0);
  useEffect(()=>{
    let active=true;
    set(previous=>({...previous,loading:true,error:null}));
    Promise.resolve().then(load).then(data=>active&&set({loading:false,data,error:null}),error=>active&&set({loading:false,data:null,error}));
    return()=>{active=false;};
  },[...deps,version]);
  return {...state,reload:()=>refresh(n=>n+1)};
}
